class Solution {
public:
    int distanceTraveled(int mainTank, int additionalTank) {
        int dist = 0;
        while (mainTank >= 5) {
            dist += 50;
            mainTank -= 5;
            if (additionalTank > 0) { additionalTank--; mainTank++; }
        }
        return dist + mainTank * 10;
    }
};

